from django.apps import AppConfig


class WebConfig(AppConfig):
    name = 'web'

    def ready(self):
        # Relax xlrd legacy 16,384 row limit for BIFF5/BIFF4 .XLS files generated by hotel ERP
        try:
            import xlrd
            from xlrd.sheet import Sheet
            if not getattr(Sheet, "_patched_for_large_biff", False):
                _orig_init = Sheet.__init__
                def _patched_init(self, *args, **kwargs):
                    _orig_init(self, *args, **kwargs)
                    self.utter_max_rows = 1048576
                Sheet.__init__ = _patched_init
                Sheet._patched_for_large_biff = True
        except Exception:
            pass

